return "#获取羁绊信息\nget_bond_info 3701 {\n    response {\n        .team {\n            id 0 : integer #羁绊组id\n            level 1 : integer #羁绊激活档位\n            plot 2 : integer #羁绊剧情观看情况，按位：0未看，1已看\n        }\n        result 0 : integer\n        teams 1 : *team #羁绊队伍\n    }\n}\n\n#激活羁绊\ndo_bond 3702 {\n    request {\n        id 0 : integer #羁绊组id\n        level 1 : integer #需要激活到第几档(1-3)\n    }\n    response {\n        result 0 : integer #1成功，2找不到羁绊组，3该档位已激活，4激活条件不满足\n        level 1 : integer #羁绊激活档位\n    }\n}\n\n#观看羁绊剧情\ndo_bond_plot 3703 {\n    request {\n        id 0 : integer #羁绊组id\n        level 1 : integer #观看第几档(1-3)的剧情\n    }\n    response {\n        result 0 : integer\n    }\n}\n\n"
